#!/bin/bash
set -euo pipefail
echo 'Writing SlackController.js...'
base64 -d > /opt/hiware-dev/src/controllers/SlackController.js << 'B64_CTRL'

B64_CTRL
echo 'Writing blockKit.js...'
base64 -d > /opt/hiware-dev/src/slack/blockKit.js << 'B64_KIT'

B64_KIT
node --check /opt/hiware-dev/src/controllers/SlackController.js
node --check /opt/hiware-dev/src/slack/blockKit.js
echo 'OK — run: pm2 restart slack-hiware-api'
